#[cfg(test)]mod cone_tests{
 use super::*;
 #[test]fn irrelevant_guard_blocks_prune_and_symmetric_triple_fault_is_rejected(){let no=u64::MAX;for conditional in[false,true]{let mut ops=vec![make(K::CCX,0,1,2,no,if conditional{0}else{no})];for _ in 0..32{ops.push(make(K::X,no,no,7,no,no));}ops.push(make(K::PushCondition,no,no,no,no,1));ops.push(make(K::X,no,no,7,no,no));ops.push(make(K::PopCondition,no,no,no,no,no));ops.push(make(K::CX,no,0,1,no,no));ops.push(make(K::X,no,no,1,no,no));ops.push(make(K::CCX,0,1,3,no,if conditional{0}else{no}));let end=ops.len()-1;let reduced=dependency_cone(&ops,0,end);assert_eq!(reduced.len(),4);assert!(local_proof(&ops,0,end,8,2));assert!(cone_local_proof(&ops,0,end,8,2));ops.remove(end-1);let end=ops.len()-1;assert!(!local_proof(&ops,0,end,8,2));assert!(!cone_local_proof(&ops,0,end,8,2));}}
 #[test]fn relevant_guarded_cancellation_is_retained_and_fault_is_rejected(){let no=u64::MAX;let ops=vec![make(K::CCX,0,1,2,no,no),make(K::PushCondition,no,no,no,no,0),make(K::CX,no,0,1,no,no),make(K::CX,no,0,1,no,no),make(K::PopCondition,no,no,no,no,no),make(K::CCX,0,1,3,no,no)];assert_eq!(dependency_cone(&ops,0,5).len(),6);assert!(local_proof(&ops,0,5,4,1));assert!(cone_local_proof(&ops,0,5,4,1));let mut bad=ops.clone();bad.remove(3);assert!(!local_proof(&bad,0,4,4,1));assert!(!cone_local_proof(&bad,0,4,4,1));}
 #[test]fn guard_snapshot_reads_before_overwrite_are_retained(){let no=u64::MAX;let ops=vec![make(K::CCX,0,1,2,no,0),make(K::PushCondition,no,no,no,no,1),make(K::BitInvert,no,no,no,0,no),make(K::X,no,no,1,no,0),make(K::PopCondition,no,no,no,no,no),make(K::CCX,0,1,3,no,0)];let reduced=dependency_cone(&ops,0,5);assert!(reduced.iter().any(|o|o.kind==K::BitInvert));assert_eq!(local_proof(&ops,0,5,4,2),cone_local_proof(&ops,0,5,4,2));assert!(!cone_local_proof(&ops,0,5,4,2));}
}
